head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.cnt = 0;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name ins_search
 * @description 예탁증서 표준코드관리  목록 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    if ((txb_pSTD_CD.getValue() === "" || txb_pSTD_CD.getValue().indexOf(" ") === "") &&
        (txb_pISU_NM.getValue() === "" || txb_pISU_NM.getValue().indexOf(" ") === "") &&
        (txb_pISUR_CD.getValue() === "" || txb_pISUR_CD.getValue().indexOf(" ") === "") &&
        (edt_pSTD_CD_GRNT_DD_SDATE.getValue() === "" || edt_pSTD_CD_GRNT_DD_SDATE.text.indexOf(" ") === "") &&
        (edt_pSTD_CD_GRNT_DD_EDATE.getValue() === "" || edt_pSTD_CD_GRNT_DD_EDATE.text.indexOf(" ") === "")) {
        await $c.win.alert("조회 파라메터가 부족합니다");
        return;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_pISU_DD_SDATE, edt_pISU_DD_EDATE) === false) {
        return false;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_pSTD_CD_GRNT_DD_SDATE, edt_pSTD_CD_GRNT_DD_EDATE) === false) {
        return false;
    }

    // 데이터셋 초기화
    dts_List.removeAll();
    dts_detail.removeAll();
    cmb_SECU_KIND_CD.setValue("");

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20220922
    fn_SetDisableSelectBtn(btn_search, true);

    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_detail
 * @description 예탁증서 표준코드관리 상세 조회한다.
 * @param {String} STD_CD STD_CD
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_detail = async function(STD_CD) {
    // 데이터셋 초기화
    dts_detail.removeAll();

    // 예탁증서 표준코드관리
    const sbmOptions = {
        id : "sbm_dts_detail",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_detail=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_modify
 * @description 예탁증서 표준코드관리 저장 , 수정 한다. screenProcsTpCd 02,03
 * @param {String} mflag mflag
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_modify = async function(mflag) {
    let screenProcsTpCd = "03";
    if (screenProcsTpCd === '03') {
        // 수정

        if (!$c.cp.isModified(dts_detail)) {
            await $c.win.alert("변경된 데이터가 없습니다.");
            return;
        }
        if (txb_STD_CD.getValue() === "" || txb_STD_CD.getValue().indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "표준코드"));
            txb_STD_CD.focus();
            return;
        }
        if (!$c.stf.checkMaxLength(txb_STD_CD, 12, "표준코드")) {
            txb_STD_CD.focus();
            return false;
        }
        if (txb_ISU_NM.getValue() === "" || txb_ISU_NM.getValue().indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목명"));
            txb_ISU_NM.focus();
            return false;
        }
        if (txb_ISU_ABBRV.getValue() === "" || txb_ISU_ABBRV.getValue().indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목약명"));
            txb_ISU_ABBRV.focus();
            return false;
        }
        if (txb_ISU_ENG_NM.getValue() === "" || txb_ISU_ENG_NM.getValue().indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목명"));
            txb_ISU_ENG_NM.focus();
            return false;
        }
        if (txb_ISU_ENG_ABBRV.getValue() === "" || txb_ISU_ENG_ABBRV.getValue().indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목약명"));
            txb_ISU_ENG_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_NM, 80, "한글종목명")) {
            txb_ISU_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ABBRV, 40, "한글종목약명")) {
            txb_ISU_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 80, "영문종목명")) {
            txb_ISU_ENG_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV, 40, "영문종목약명")) {
            txb_ISU_ENG_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txa_NUSUAL_ISU_COND_CONTN, 60, "특이발행조건")) {
            // txb_ISU_ENG_ABBRV.value = "";
            txa_NUSUAL_ISU_COND_CONTN.focus();
            return false;
        }
        if (mflag === "N") return;
        trs_Save.KeyName = "toinb_dataid4";
        // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     EMP_NO : js_emp_no,
        //     EMP_NM : js_emp_nm
        // };
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/StdCdDrInfoAction.do",
            ref : "dts_detail",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name ins_remove
 * @description 표준코드 삭제
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_remove = async function() {
    let screenProcsTpCd = "04";
    // dts_Delete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    dts_Delete.insertRow();
    dts_Delete.setCellData(1, "STD_CD", dts_detail.getCellData(dts_detail.getRowPosition(), "STD_CD"));
    dts_Delete.setCellData(1, "ISU_NM", dts_detail.getCellData(dts_detail.getRowPosition(), "ISU_NM"));
    dts_Delete.setCellData(1, "CHG_RSN", txb_DEL_RSN.getValue());
    trs_Delete.KeyName = "toinb_dataid4";
    // [전환검토] trs_Delete.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm
    // };
    const sbmOptions = {
        id : "sbm_trs_Delete",
        action : "/StdCdDrInfoAction.do",
        ref : "dts_Delete",
        target : "trs_Delete=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name Change_cfi
 * @description 보통주의 cfi 변경 설정하기...
 * @returns {void}
 * @hidden N
 */
scwin.Change_cfi = function() {
    // Cfi의 콤보 박스를 변경할 경우....
    let cfi = "EMXXX";
    const secu_kind_cd = cmb_SECU_KIND_CD.getValue();
    if (secu_kind_cd === "") {
        cfi += "_";
    } else {
        cfi += secu_kind_cd;
    }
    txb_CFI_CD.setValue(cfi);
};

/**********************************************
 * 함수명   : fn_GetParam
 * 설명       : 전달값을 정의한다.
 ***********************************************/
scwin.arrPar = new Array();

/**
 * @method
 * @name getParam
 * @description get Param 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // 표준코드 OR 발행기관 코드
    scwin.arrPar[1] = txb_param2.getValue();

    // alert(arrPar[0] + " " + arrPar[1]);
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

