/**
 * @method
 * @name changeCfi
 * @description cfi 변경 설정
 * @returns {void}
 * @hidden N
 */
scwin.changeCfi = function() {
    // Cfi의 콤보 박스를 변경할 경우....
    let cfi = "";
    let str_cfi = dts_detail.getCellData(dts_detail.getRowPosition(), "CFI_CD");
    let temp = cmb_cb_p_group.getValue(); // 선택된그룹

    // 카테고리셋팅
    if (temp === "") {
        cfi = "_";
    } else if (temp === "E") {
        cfi = "E";
    } else if (temp === "D") {
        cfi = "D";
    } else if (temp === "R") {
        cfi = "R";
    }

    // 그룹
    if (cmb_cb_p_group.getValue() === "") cfi += "_";

    else cfi += "D"; // cfi += getObjectValue(cmb_cb_p_group);

    // 1차속성
    if (cmb_cb_p_attr_1.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_1.getValue();

    // 2차속성
    if (cmb_cb_p_attr_2.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_2.getValue();

    // 3차속성
    if (cmb_cb_p_attr_3.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_3.getValue();

    // 4차속성
    if (cmb_cb_p_attr_4.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_4.getValue();
    txb_CFI_CD.setValue(cfi); // cfi 설정

};

/**
 * @method
 * @name setChange
 * @description 상세 조회시 CFI 상세 설정
 * @param {String} str_cfi str_cfi
 * @returns {void}
 * @hidden N
 */
scwin.setChange = function(str_cfi) {
    if (str_cfi === "") return;
    ins_cfi_set(dts_cfi_group, "ULDINS15600.xml", SCREN_PROCS_TP_CD_01, "06", "E", "", "", "G");
    ins_cfi_set(dts_cfi_group_1, "ULDINS15600.xml", SCREN_PROCS_TP_CD_01, "06", "D", "", "", "G");
    ins_cfi_set(dts_cfi_group_2, "ULDINS15600.xml", SCREN_PROCS_TP_CD_01, "06", "R", "", "", "G");

    // 하나의 데이터셋으로 합치기
    dts_cfi_group.setBroadcast(false);
    for (let i = 2; i < dts_cfi_group_1.getRowCount() + 1; i++) {
        dts_cfi_group.insertRow();
        dts_cfi_group.setCellData(dts_cfi_group.getRowCount(), "VALUE", dts_cfi_group_1.getCellData(i, "VALUE"));
        dts_cfi_group.setCellData(dts_cfi_group.getRowCount(), "TEXT", dts_cfi_group_1.getCellData(i, "TEXT"));
    }
    dts_cfi_group.setBroadcast(true, true);
    dts_cfi_group.setBroadcast(false);
    for (let i = 2; i < dts_cfi_group_2.getRowCount() + 1; i++) {
        dts_cfi_group.insertRow();
        dts_cfi_group.setCellData(dts_cfi_group.getRowCount(), "VALUE", dts_cfi_group_2.getCellData(i, "VALUE"));
        dts_cfi_group.setCellData(dts_cfi_group.getRowCount(), "TEXT", dts_cfi_group_2.getCellData(i, "TEXT"));
    }
    dts_cfi_group.setBroadcast(true, true);

    // DR 특수케이스
    let temp = str_cfi.substring(0, 2); // 카테고리 + 그룹
    // alert(temp);
    if (temp === "ED") {
        cmb_cb_p_group.setValue("E");
    } else if (temp === "DD") {
        cmb_cb_p_group.setValue("D");
    } else if (temp === "RD") {
        cmb_cb_p_group.setValue("R");
    }
    // setObjectValue(cmb_cb_p_group,str_cfi.substring(1, 2));
    cmb_cb_p_attr_1.setValue(str_cfi.substring(2, 3));
    cmb_cb_p_attr_2.setValue(str_cfi.substring(3, 4));
    cmb_cb_p_attr_3.setValue(str_cfi.substring(4, 5));
    cmb_cb_p_attr_4.setValue(str_cfi.substring(5, 6));
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    // PanelToGroupBox(panel_3);
    txb_pSTD_CD.setValue("KR8");
    ins_combo_set(dts_STD_CD_APCT_TP_CD, "ULDINS15600.xml", SCREN_PROCS_TP_CD_01, "03527"); // 03527 - 신청자구분

    /*
    cmb_PREFSTK_YN <- 보통주/우선주 ->  도메인 미존재 하드코딩으로 콤보로 만든다.
     */
    ins_combo_set(dts_CNTR_CD, "ULDINS15600.xml", SCREN_PROCS_TP_CD_01, "01371", "SEL");
    ins_combo_set(dts_NEWSTK_KIND_CD, "ULDINS15600.xml", SCREN_PROCS_TP_CD_01, "03428", "SEL");
    ins_combo_set(dts_BAS_SECU_KIND_CD, "ULDINS15600.xml", SCREN_PROCS_TP_CD_01, "03426", "SEL");
    ins_combo_set(dts_DOM_FORN_ISU_TP_CD, "ULDINS15600.xml", SCREN_PROCS_TP_CD_01, "03407", "SEL");
    ins_combo_set(dts_CURR_TP_CD, "ULDINS15600.xml", SCREN_PROCS_TP_CD_01, "02475", "SEL");
    ins_combo_set(dts_LIST_STAT_CD, "ULDINS15600.xml", SCREN_PROCS_TP_CD_01, "00714", "SEL"); // 00714 - D:상장폐지I:미발행N:비상장Y:상장Z:기타
    fn_CtrlBtn_temp("no_data");

    // hidden패널
    panel_12.hide();
    const arrObjectApct = [txb_APCT_NM, txb_APCT_FAX_NO, txb_APCT_TEL_NO, txb_APCT_INNR_NO];
    for (let i = 0; i < arrObjectApct.length; i++) {
        fn_apct_delchar(arrObjectApct[i]);
    }
    txb_pSTD_CD.focus();
};

/**
 * @method
 * @name btn_file_onclick
 * @description 「첨부파일확인」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_file_onclick = function() {
    /*
    txb_param1 에는 신청ID
    txb_param2 에는 구분값을 넣는데..
     + "1 : 발행기관신청, 팩스-발행기관신청 \n"
     + "2 : 표준코드신청, 팩스-표준코드신청 \n"
     + "3 : 팩스-다운로드IP 로 값을 넣어주세요.\n"
     */
    txb_param1.setValue(dts_detail.getCellData(1, "STD_CD_APPL_ID")); // 표준코드 신청 ID
    txb_param2.setValue("2");
    fn_GetPar = scwin.getParam;
    ins_popupOpen("", "", "ULDINS91100", "첨부파일", "655", "350");
};

