/**
 * @method
 * @name cmb_cb_p_group_onselchange
 * @description cmb_cb_p_group onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_cb_p_group_onselchange = function() {
    if (cmb_cb_p_group.getValue() !== "") {
        let str_cfi = dts_detail.getCellData(dts_detail.getRowPosition(), "CFI_CD");
        const temp1 = ""; // str_cfi.substring(0, 1);//카테고리 cfi첫자리
        const temp2 = cmb_cb_p_group.getValue(); // 선택한 그룹
        let productDiv = "";
        let categoryDiv = "";

        // 그룹에따라 [상품구분, 카테고리] 셋팅
        productDiv = "06";
        if (temp2 === "E") {
            // 주권예탁증서
            categoryDiv = "E";
        } else if (temp2 === "D") {
            // 채무증권예탁증서
            categoryDiv = "D";
        } else if (temp2 === "R") {
            // 권리예탁증서
            categoryDiv = "R";
        }
        ins_cfi_set(dts_cfi_attr1, "ULDINS15600.xml", SCREN_PROCS_TP_CD_01, productDiv, categoryDiv, temp2, "1", "");
        ins_cfi_set(dts_cfi_attr2, "ULDINS15600.xml", SCREN_PROCS_TP_CD_01, productDiv, categoryDiv, temp2, "2", "");
        ins_cfi_set(dts_cfi_attr3, "ULDINS15600.xml", SCREN_PROCS_TP_CD_01, productDiv, categoryDiv, temp2, "3", "");
        ins_cfi_set(dts_cfi_attr4, "ULDINS15600.xml", SCREN_PROCS_TP_CD_01, productDiv, categoryDiv, temp2, "4", "");
        // alert(dts_cfi_attr1.NameValue(2,"HEAD_NM"));
        label_attr1.setValue("(" + dts_cfi_attr1.getCellData(2, "HEAD_NM") + ")");
        label_attr2.setValue("(" + dts_cfi_attr2.getCellData(2, "HEAD_NM") + ")");
        label_attr3.setValue("(" + dts_cfi_attr3.getCellData(2, "HEAD_NM") + ")");
        label_attr4.setValue("(" + dts_cfi_attr4.getCellData(2, "HEAD_NM") + ")");
    }
    scwin.changeCfi();
};
